export class VisionSensor extends Sensor {
    /**
     * Events this sensor can emit.
     * @type {string[]}
     * @static
     */
    static events: string[];
    /**
     * Create a new VisionSensor.
     *
     * @param {Object} [config] - Configuration options.
     * @param {number} [config.fov=90] - Field of view in degrees.
     * @param {number} [config.range=30] - Maximum vision range.
     * @param {number} [config.rayCount=5] - Number of rays per scan.
     * @param {string[]} [config.targetTypes=['dynamic']] - Body types to detect.
     * @param {number} [config.eyeHeight=1.5] - Height offset for ray origin.
     * @param {number} [config.updatePeriod=0.1] - Update interval in seconds.
     */
    constructor(config?: {
        fov?: number;
        range?: number;
        rayCount?: number;
        targetTypes?: string[];
        eyeHeight?: number;
        updatePeriod?: number;
    });
    /**
     * Field of view in degrees.
     * @type {number}
     * @private
     */
    private _fov;
    /**
     * Maximum vision range.
     * @type {number}
     * @private
     */
    private _range;
    /**
     * Number of rays per scan.
     * @type {number}
     * @private
     */
    private _rayCount;
    /**
     * Body types to detect.
     * @type {string[]}
     * @private
     */
    private _targetTypes;
    /**
     * Height offset for ray origin.
     * @type {number}
     * @private
     */
    private _eyeHeight;
    /**
     * Half FOV in radians (cached).
     * @type {number}
     * @private
     */
    private _halfFovRad;
    /**
     * Previous target visibility state for change detection.
     * @type {boolean}
     * @private
     */
    private _wasTargetVisible;
    /**
     * Set field of view.
     *
     * @param {number} value - FOV in degrees.
     */
    set fov(value: number);
    /**
     * Get field of view.
     *
     * @returns {number} FOV in degrees.
     */
    get fov(): number;
    /**
     * Set vision range.
     *
     * @param {number} value - Range in units.
     */
    set range(value: number);
    /**
     * Get vision range.
     *
     * @returns {number} Range in units.
     */
    get range(): number;
    /**
     * Configure sensor parameters.
     *
     * @param {Object} config - Configuration object.
     * @returns {VisionSensor} This instance for chaining.
     */
    set(config: any): VisionSensor;
}
import { Sensor } from './Sensor.js';
